mapper.select:
SELECT x.kind AS "kind", x.category AS "category", x.label AS "label" FROM (
SELECT a.kind, a.category, a.key, a.label FROM trial_after a WHERE NOT EXISTS (SELECT 1 FROM trial_before b WHERE b.kind = a.kind AND b.key = a.key)
SELECT b.kind, b.category, b.key, b.label FROM trial_before b WHERE NOT EXISTS (SELECT 1 FROM trial_after a WHERE a.kind = b.kind AND a.key = b.key)
) x ORDER BY x.kind, x.category, x.label LIMIT #{limit}

WITH covered(ref_kind, name, arg_index) AS (
VALUES (#{c.kind}::text, #{c.name}::text, #{c.argIndex}::int)
SELECT NULL::text, NULL::text, NULL::int WHERE FALSE
), arg AS ( SELECT r.ref_kind, r.name, 0 AS arg_index, r.arg_text AS text, r.from_id, r.file_id, r.line_start FROM analysis_reference r WHERE r.revision_id = #{revisionId} AND r.from_kind = 'METHOD' AND r.ref_kind IN ('CALL', 'CREATE') AND r.arg_text IS NOT NULL UNION ALL SELECT r.ref_kind, r.name, (e.ord - 1)::int, e.text, r.from_id, r.file_id, r.line_start FROM analysis_reference r CROSS JOIN LATERAL jsonb_array_elements_text(r.args_json) WITH ORDINALITY AS e(text, ord) WHERE r.revision_id = #{revisionId} AND r.from_kind = 'METHOD' AND r.ref_kind IN ('CALL', 'CREATE') AND r.args_json IS NOT NULL AND e.text IS NOT NULL ), lit AS MATERIALIZED ( SELECT a.ref_kind, a.name, a.arg_index, a.from_id, a.file_id, a.line_start , regexp_replace(trim(both '"' from a.text), '^/+', '') AS value FROM arg a WHERE a.text ~ '^"[A-Za-z0-9_./-]{1,200}"$' AND NOT EXISTS (SELECT 1 FROM covered c WHERE c.ref_kind = a.ref_kind AND c.name = a.name AND c.arg_index = a.arg_index) ), stmt AS MATERIALIZED ( -- "네임스페이스.id" 와, 프로젝트에 하나뿐인 id(iBATIS 처럼 id 만 넘기는 방식. MapperLinker 도 이때만 잇는다) SELECT COALESCE(namespace || '.', '') || statement_id AS name FROM analysis_mapper WHERE revision_id = #{revisionId} AND statement_type <> 'SQL_FRAGMENT' UNION SELECT statement_id FROM analysis_mapper WHERE revision_id = #{revisionId} AND statement_type <> 'SQL_FRAGMENT' GROUP BY statement_id HAVING COUNT(*) = 1 ), view_hit AS MATERIALIZED ( -- 글자에 .jsp 를 붙인 경로로 끝나는 JSP 가 있는 값. 파일 이름으로 먼저 맞춘 뒤(해시 조인) 경로 끝을 본다 SELECT DISTINCT v.value FROM (SELECT DISTINCT value FROM lit) v JOIN analysis_file f ON f.revision_id = #{revisionId} AND f.language = 'JSP' AND regexp_replace(f.path, '^.*/', '') = regexp_replace(v.value, '^.*/', '') || '.jsp' WHERE f.path = v.value || '.jsp' OR right(f.path, length(v.value) + 5) = '/' || v.value || '.jsp' ), scored AS ( SELECT l.*, (s.name IS NOT NULL) AS is_sql, (vh.value IS NOT NULL) AS is_view FROM lit l LEFT JOIN stmt s ON s.name = l.value LEFT JOIN view_hit vh ON vh.value = l.value ), grouped AS ( -- 맞는 것이 2건 이상이고, 글자로 넘긴 호출의 30% 이상이 맞아야 후보로 본다. -- equals("orderList") 처럼 우연히 이름이 같은 글자를 쓰는 호출을 거르려는 것이다. SELECT ref_kind, name, arg_index , COUNT(*) AS calls , COUNT(*) FILTER (WHERE is_sql) AS sql_matches , COUNT(*) FILTER (WHERE is_view) AS view_matches , (array_agg(DISTINCT value) FILTER (WHERE is_sql OR is_view))[1:3] AS samples FROM scored GROUP BY ref_kind, name, arg_index HAVING GREATEST(COUNT(*) FILTER (WHERE is_sql), COUNT(*) FILTER (WHERE is_view)) >= 2 AND GREATEST(COUNT(*) FILTER (WHERE is_sql), COUNT(*) FILTER (WHERE is_view)) * 10 >= COUNT(*) * 3 ) SELECT g.ref_kind AS "kind", g.name AS "name", g.arg_index AS "argIndex", g.calls AS "calls" , g.sql_matches AS "sqlMatches", g.view_matches AS "viewMatches", array_to_string(g.samples, ', ') AS "samples" , rt.type AS "receiverType", rt.n AS "receiverTypeCalls" FROM grouped g LEFT JOIN LATERAL ( -- 그 호출이 RESOLVE 에서 가장 많이 풀린 대상 타입. receiverTypes 를 적을 때 참고한다 SELECT COALESCE(ts.fqn, regexp_replace(c.to_external, '\.[^.(]+(\(.*)?$', '')) AS type, COUNT(*) AS n FROM lit l JOIN analysis_relation c ON c.revision_id = #{revisionId} AND c.relation_type = 'CALLS' AND c.from_id = l.from_id AND c.file_id = l.file_id AND c.line_start = l.line_start LEFT JOIN analysis_method tm ON tm.revision_id = c.revision_id AND tm.method_id = c.to_id LEFT JOIN analysis_symbol ts ON ts.revision_id = tm.revision_id AND ts.symbol_id = tm.owner_symbol_id WHERE g.ref_kind = 'CALL' AND l.ref_kind = g.ref_kind AND l.name = g.name AND l.arg_index = g.arg_index AND (tm.name = l.name OR c.to_external LIKE '%.' || l.name || '(%' OR c.to_external LIKE '%.' || l.name) GROUP BY 1 ORDER BY 2 DESC LIMIT 1) rt ON TRUE -- JDK 의 메소드(String.equals 등)는 관례가 아니다 WHERE rt.type IS NULL OR rt.type NOT LIKE 'java.%' ORDER BY GREATEST(g.sql_matches, g.view_matches) DESC, g.ref_kind, g.name, g.arg_index LIMIT #{limit}

SELECT a.annotation_name AS "annotation", a.target_kind AS "targetKind", MIN(a.annotation_fqn) AS "fqn" , COUNT(*) AS "count" , COUNT(*) FILTER (WHERE (a.target_kind = 'TYPE' AND (s.layer IS NULL OR s.layer_confidence = 'LOW')) OR (a.target_kind = 'METHOD' AND NOT EXISTS ( SELECT 1 FROM analysis_endpoint e WHERE e.revision_id = a.revision_id AND e.method_id = a.target_id))) AS "unexplained" FROM analysis_annotation a LEFT JOIN analysis_symbol s ON a.target_kind = 'TYPE' AND s.revision_id = a.revision_id AND s.symbol_id = a.target_id WHERE a.revision_id = #{revisionId} AND a.target_kind IN ('TYPE', 'METHOD')
AND a.annotation_name NOT IN #{n}
AND a.annotation_name NOT IN #{n} GROUP BY a.annotation_name, a.target_kind HAVING COUNT(*) >= 2 ORDER BY 5 DESC, 4 DESC, 1 LIMIT #{limit}

SELECT COALESCE(r.to_external, t.fqn) AS "superType" , (r.to_external IS NULL) AS "inProject" , COUNT(DISTINCT r.from_id) AS "types" , COUNT(DISTINCT r.from_id) FILTER (WHERE s.layer IS NULL OR s.layer_confidence = 'LOW') AS "unlayered" , array_to_string((array_agg(DISTINCT s.simple_name))[1:3], ', ') AS "samples" FROM analysis_relation r JOIN analysis_symbol s ON s.revision_id = r.revision_id AND s.symbol_id = r.from_id AND s.kind <> 'ANONYMOUS' LEFT JOIN analysis_symbol t ON t.revision_id = r.revision_id AND t.symbol_id = r.to_id WHERE r.revision_id = #{revisionId} AND r.relation_type IN ('EXTENDS', 'IMPLEMENTS') AND COALESCE(r.to_external, t.fqn) IS NOT NULL AND COALESCE(r.to_external, t.fqn) NOT LIKE 'java.%'
AND COALESCE(r.to_external, t.fqn) NOT IN #{n}
GROUP BY 1, 2 HAVING COUNT(DISTINCT r.from_id) >= 3 AND COUNT(DISTINCT r.from_id) FILTER (WHERE s.layer IS NULL OR s.layer_confidence = 'LOW') > 0 ORDER BY 4 DESC, 3 DESC, 1 LIMIT #{limit}
